python3 - <<'EOF'
import yaml, re, subprocess

d = yaml.safe_load(open('lab/synthetic/clients/almeida_paulo/masterkey.yaml'))

tokens = set()

def add(t):
    if t is None: return
    t = str(t).strip()
    if not t: return
    tokens.add(t)

# proper nouns / identifiers invented or carried
add(d['identity']['family_name']); add(d['identity']['given_name']); add(d['identity']['middle_name'])
add(d['identity']['full_legal_name']); add(d['identity']['ssn']); add(d['identity']['ssn'].replace('-',''))
add(d['contact']['email']); add(d['contact']['daytime_phone']); add(d['contact']['mobile_phone'])
add(d['immigration']['a_number']); add(d['immigration']['a_number_formatted'])

for a in d['addresses']:
    add(a['street']); add(a['city']); add(a['zip'])
for e in d['employment']:
    add(e['employer']); add(e['city']); add(e['zip'])
for t in d['travel']['trips']:
    for c in t['countries']: add(c)

p = d['documents']['passport']
add(p['number']); add(p['number'].replace('<','')); add(p['issue_date'].replace('-','')); add(p['expiry_date'].replace('-',''))
add(p['mrz']['line1'].replace('<','')); add(p['mrz']['line2'].replace('<',''))

gc = d['documents']['green_card']
add(gc['card_expiry'].replace('-',''))

tr = d['documents']['tax_return']
add(tr['preparer_name']); add(tr['taxpayer_name'])
add(str(tr['wages'])); add(str(tr['agi'])); add(str(tr['total_tax'])); add(str(tr['refund_or_owed']['amount']))

for od in d['documents']['over_delivered']:
    for k,v in od.items():
        if isinstance(v,str): add(v)
        if isinstance(v,dict):
            for vv in v.values(): add(vv)

add(d['matter']['fee'])

# keep only whole-token candidates: proper-noun-like strings and digit strings >=6 chars
candidates = set()
for t in tokens:
    if re.fullmatch(r'\d+', t):
        if len(t) >= 6:
            candidates.add(t)
    else:
        candidates.add(t)

results = []
hits = 0
for t in sorted(candidates):
    r = subprocess.run(['grep','-ixF', t, 'lab/synthetic/blocklist.txt'], capture_output=True, text=True)
    if r.returncode == 0:
        hits += 1
        results.append((t, 'HIT'))
    else:
        results.append((t, 'clean'))

for t, status in results:
    print(status, repr(t))
print()
print("total tokens checked:", len(candidates))
print("total hits:", hits)
EOF

